function ClientVersusDisarmed(float ServerEndTime)
{
    local HPVersusWand W;

    VersusDisarmEndTime = FMax(VersusDisarmEndTime, ServerEndTime);
    VersusSpellLockEndTime = FMax(VersusSpellLockEndTime, ServerEndTime);
